import {repairReviews,repairDay,repairMonth,repairGoalKey,readRepairGoal} from './workshop-repair-review.mjs';
export function mountRepairReviews({language,host,faultName,launch,available,onGoalChange=()=>{}}){
 const root=document.createElement('section');root.id='repairCalendar';root.className='challenge-panel';host.before(root);let month=repairDay().slice(0,7),selected=repairDay(),goal=2,error=false,lastRows=[];
 try{goal=readRepairGoal(localStorage);}catch{error=true;}
 const t=(es,en)=>language()==='es'?es:en;
 const dateLabel=day=>new Date(day+'T12:00:00Z').toLocaleDateString(language(),{timeZone:'UTC',year:'numeric',month:'long',day:'numeric'});
 function render(rows=lastRows){lastRows=rows;const model=repairReviews(rows);root.replaceChildren();const add=(tag,text,parent=root)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};
 add('h2',t('Calendario de repaso de reparaciones','Spaced repair reviews'));add('p',t('Zona horaria: Bogotá. Un repaso limpio por día amplía el intervalo: 1, 3, 7, 14 y 30 días. Se requiere nota ≥90, máximo una pista, sin intervenciones innecesarias ni verificaciones fallidas. Si te cuesta, vuelve mañana; repetir el mismo día no acelera el intervalo.','Time zone: Bogotá. A clean review day increases the interval: 1, 3, 7, 14 and 30 days. Requires score ≥90, at most one hint, no unnecessary interventions or failed checks. A difficult attempt returns tomorrow; repeating on the same day cannot accelerate the interval.'));
 const stats=add('p',t('Hoy: ','Today: ')+model.completed+'/'+goal+t(' averías distintas verificadas · Racha: ',' distinct faults verified · Streak: ')+model.streak+t(' días',' days'));stats.id='repairDailyStatus';stats.setAttribute('role','status');const progress=add('progress','');progress.max=goal;progress.value=Math.min(goal,model.completed);progress.setAttribute('aria-label',t('Meta diaria','Daily goal'));
 if(model.completed>=goal)add('p',t('¡Meta diaria completada!','Daily goal complete!'));
 const label=add('label',t('Meta diaria ','Daily goal ')),select=add('select','',label);select.id='repairGoal';for(let n=1;n<=5;n++){const option=add('option',String(n),select);option.value=n;}select.value=goal;select.onchange=()=>{goal=+select.value;try{localStorage.setItem(repairGoalKey,goal);error=false;}catch{error=true;}render();onGoalChange();};if(error)add('p',t('No se pudo guardar la meta. Vuelve a seleccionarla para reintentar.','Goal could not be saved. Select it again to retry.')).setAttribute('role','alert');
 add('p',t('La meta cuenta averías distintas verificadas al día; la racha requiere al menos una. Las notas de examen y las reparaciones incompletas no cuentan. Cálculos basados en tus últimas 100 reparaciones guardadas.','The goal counts distinct verified faults per day; the streak needs at least one. Exam scores and unfinished repairs do not count. Calculations use your latest 100 saved repairs.'));
 const nav=add('div','');nav.className='controls';for(const [delta,text]of [[-1,t('Mes anterior','Previous month')],[1,t('Mes siguiente','Next month')]]){const b=add('button',text,nav);b.onclick=()=>{const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+delta);month=d.toISOString().slice(0,7);selected=month+'-01';render();};}const today=add('button',t('Hoy','Today'),nav);today.onclick=()=>{selected=model.today;month=selected.slice(0,7);render();};
 add('h3',new Date(month+'-01T12:00:00Z').toLocaleDateString(language(),{timeZone:'UTC',month:'long',year:'numeric'}));const grid=add('div','');grid.className='repair-calendar-grid';for(const day of (language()==='es'?['L','M','X','J','V','S','D']:['M','T','W','T','F','S','S']))add('span',day,grid);
 for(const day of repairMonth(month)){const due=model.entries.filter(e=>e.due===day||day===model.today&&e.due<day).length,completed=model.counts[day]||0,b=add('button',Number(day.slice(-2))+'\n'+(due?'● '+due:'')+(completed?'\n✓ '+completed:''),grid);b.dataset.reviewDay=day;b.classList.toggle('outside-month',day.slice(0,7)!==month);b.setAttribute('aria-pressed',String(day===selected));if(day===model.today)b.setAttribute('aria-current','date');b.setAttribute('aria-label',dateLabel(day)+': '+due+t(' pendientes, ',' due, ')+completed+t(' verificadas',' verified'));b.onclick=()=>{selected=day;render();};}
 add('p',t('● Repasos pendientes · ✓ Averías verificadas','● Due reviews · ✓ Verified faults'));
 add('h3',dateLabel(selected));add('p',t('Pendientes previstos; los vencidos se incluyen hoy. El calendario se actualiza al practicar y no presupone repasos futuros completados.','Projected due reviews; overdue items are included today. The calendar updates with practice and does not assume future reviews are completed.'));
 const due=model.entries.filter(e=>e.due===selected||selected===model.today&&e.due<selected);if(!due.length)add('p',model.entries.length?t('No hay repasos pendientes para esta fecha.','No reviews due on this date.'):t('Verifica tu primera reparación para crear un plan personalizado.','Verify your first repair to create a personalized plan.'));
 for(const e of due){const card=add('article','');add('p',faultName(e)+' · '+(e.overdue?t('Vencido · ','Overdue · '):'')+t('Última práctica: ','Last practice: ')+dateLabel(e.last),card);const b=add('button',selected>model.today?t('Practicar antes de tiempo','Practise early'):t('Iniciar repaso','Start review'),card);b.dataset.spacedRepair=e.key;b.disabled=!available();b.onclick=()=>launch(e);}
 if(!available())add('p',t('Abre un examen completado para entrar a los bancos de reparación.','Open a completed exam to enter the repair benches.'));
 }
 let lastDay=repairDay();
 function rollover(){const today=repairDay();if(today!==lastDay){if(selected===lastDay){selected=today;month=today.slice(0,7);}lastDay=today;render();}}
 setInterval(rollover,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)rollover();});
 return {render};
}
